{
  "action": "send",
  "subject": "2027 agreement – final fixed-price adjustment",
  "body": "Dear Ms Lechner,\n\nThank you for accepting the package and recognising the volume outlook. We respect your decision not to disclose the calculation.\n\nYour message favours a fixed price, while the attached offer retains copper indexation. To align the agreement with your preference for predictable administration, we can increase the unit price to €349.50 if you remove the index clause and extend payment to 60 days net.\n\nThis gives you a modest price improvement in exchange for fixed pricing and the longer payment period. All other enquiry terms remain unchanged.\n\nCould you confirm this final adjustment? We would then proceed with the agreement.\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 349.5,
      "payment_days": 60,
      "index_clause": null
    }
  ],
  "rationale": "Nordmark accepted the indexed package but expressed a preference for fixed pricing. This is the required single test after agreement: a small price give-back in exchange for removing index exposure and improving payment terms.",
  "target_price": 349.5
}

