  "action": "settle",
  "subject": "Acceptance of 2027 motor supply agreement",
  "body": "Dear Ms Lechner,\n\nThank you for confirming the agreement and clarifying the payment and index terms.\n\nWe accept your attached offer at €349.00 per unit, payment 30 days net, with CU-NOTATION indexation using a 20% material share, 5% deadband and August 2026 base month.\n\nThe agreement covers 6,110 units annually for 12 months from 1 January 2027, with 35-day lead time, DAP delivery and no tooling charge, as stated in your offer.\n\nWe will proceed with the order documentation. Thank you for your constructive cooperation; we look forward to continuing our relationship.\n\nKind regards,\nHollerau Pumpenwerke, Purchasing",
  "term_sheets": [
    {
      "unit_price": 349.0,
      "payment_days": 30,
      "index_clause": {
        "series": "CU-NOTATION",
        "material_share": 0.2,
        "deadband_pct": 5,
        "base_month": "2026-08"
      }
    }
  ],
  "rationale": "The single post-agreement test did not secure improved terms: Credit Control retained 30 days and Legal retained copper indexation. Settle the confirmed package rather than reopen an already agreed offer.",
  "target_price": 349.0
}
